let todos = [];

const todoInput = document.getElementById('todoInput');
const prioritySelect = document.getElementById('prioritySelect');
const addBtn = document.getElementById('addBtn');
const todoList = document.getElementById('todoList');
const emptyState = document.getElementById('emptyState');

// 통계
const totalCount = document.getElementById('totalCount');
const completedCount = document.getElementById('completedCount');
const remainingCount = document.getElementById('remainingCount');

// 앱 시작
function init() {
  todos = window.electronAPI.loadTodos();
  render();
}

function addTodo() {
  const text = todoInput.value.trim();
  if (!text) {
    alert('할 일을 입력해주세요!');
    return;
  }

  const todo = {
    id: Date.now(),
    text,
    priority: prioritySelect.value,
    completed: false,
    createdAt: new Date().toLocaleDateString('ko-KR'),
  };

  todos.push(todo);
  save();
  todoInput.value = '';
  prioritySelect.value = 'medium';
  render();
}

function toggleTodo(id) {
  const todo = todos.find(t => t.id === id);
  if (todo) {
    todo.completed = !todo.completed;
    save();
    render();
  }
}

function deleteTodo(id) {
  todos = todos.filter(t => t.id !== id);
  save();
  render();
}

function save() {
  window.electronAPI.saveTodos(todos);
}

function render() {
  todoList.innerHTML = '';

  if (todos.length === 0) {
    emptyState.style.display = 'block';
  } else {
    emptyState.style.display = 'none';
  }

  todos.forEach(todo => {
    const li = document.createElement('li');
    li.className = `todo-item ${todo.priority} ${todo.completed ? 'completed' : ''}`;

    const priorityLabels = { high: '높음', medium: '중간', low: '낮음' };

    li.innerHTML = `
      <input type="checkbox" class="todo-checkbox" ${todo.completed ? 'checked' : ''} />
      <div class="todo-content">
        <div class="todo-text">${escapeHtml(todo.text)}</div>
        <div class="todo-meta">
          <span class="priority-badge ${todo.priority}">${priorityLabels[todo.priority]}</span>
          ${todo.createdAt}
        </div>
      </div>
      <button class="todo-delete">삭제</button>
    `;

    li.querySelector('input').addEventListener('change', () => toggleTodo(todo.id));
    li.querySelector('button').addEventListener('click', () => deleteTodo(todo.id));

    todoList.appendChild(li);
  });

  updateStats();
}

function updateStats() {
  const total = todos.length;
  const completed = todos.filter(t => t.completed).length;
  const remaining = total - completed;

  totalCount.textContent = total;
  completedCount.textContent = completed;
  remainingCount.textContent = remaining;
}

function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

addBtn.addEventListener('click', addTodo);
todoInput.addEventListener('keypress', e => {
  if (e.key === 'Enter') addTodo();
});

init();
EOF
